__d(function(g,r,i,a,m,_e,d){"use strict";Object.defineProperty(_e,'__esModule',{value:!0}),Object.defineProperty(_e,"default",{enumerable:!0,get:function(){return c}});var e,o=r(d[0]),n=(e=o)&&e.__esModule?e:{default:e},s=r(d[1]),t=r(d[2]);function c(){return(0,t.jsxs)(s.Page,{title:"PRIVACY",back:!0,children:[(0,t.jsx)(s.Copy,{kind:"title",children:"Your data, explained."}),(0,t.jsx)(s.Copy,{children:"SuppClarity \xb7 MedResearch Academy \xb7 Updated November 22, 2026"}),(0,t.jsxs)(s.Card,{children:[(0,t.jsx)(s.Copy,{kind:"heading",children:"On your device"}),(0,t.jsx)(s.Copy,{children:"The installed iPhone and Android app saves your questionnaire answers, confirmed products, questionnaire progress and reading size in encrypted device storage, together with optional reminders and routine history. There is no app account, cloud sync, advertising or tracking SDK. The browser preview keeps entries in memory and clears on reload. Chat history stays in memory for this session and is not persisted with your routine. Selected photos are not saved as routine entries."}),(0,t.jsx)(s.Copy,{children:"Use Your space \u2192 Clear my data to remove saved answers and products. Keep an export if you need a copy. Device storage can fail; an error will be shown. On iOS, keychain entries may survive reinstalling the app, so clear data inside the app before uninstalling. Android encrypted entries are excluded from device backup. Temporary photo files may remain under the device or photo library\u2019s own controls."})]}),(0,t.jsxs)(s.Card,{children:[(0,t.jsx)(s.Copy,{kind:"heading",children:"Optional Plus subscriptions"}),(0,t.jsx)(s.Copy,{children:"When subscriptions are enabled, RevenueCat and Apple or Google process a separate random billing identifier, purchase and renewal records, product identifiers and operational device or network information to provide purchases, restore access, prevent abuse and report subscription activity in the RevenueCat dashboard. We do not send your questionnaire, label photos, routine entries or conversations to RevenueCat. Your payment details are handled by the store. An opaque billing identifier is also sent to our server when you request online help so we can verify your entitlement and allowance. It is kept separate from your local health entries."}),(0,t.jsx)(s.Copy,{children:"Monthly usage counters contain keyed hashes and counts, not question or photo contents, and are removed after at most 63 days. Clearing local entries does not cancel a subscription or erase store transaction records. Manage or cancel through your store account; contact us for privacy requests concerning subscription records. Billing providers retain records under their own policies and legal obligations."}),(0,t.jsx)(s.Copy,{children:"Reminders are scheduled on your phone only after you choose them and allow notifications. Alerts use generic wording. PDF summaries are generated locally and shared only through the phone sharing screen you open. Temporary generated PDFs are deleted by the app after sharing; copies retained by recipients or other apps are outside that deletion."})]}),(0,t.jsxs)(s.Card,{children:[(0,t.jsx)(s.Copy,{kind:"heading",children:"When you choose online help"}),(0,t.jsx)(s.Copy,{children:"Photo reading: with your permission, the selected image is sent through our server to OpenAI to transcribe its visible label. Avoid including faces, prescriptions or personal details. Your questionnaire is not included. If a readable name or brand needs an online match, it is used for product search."}),(0,t.jsx)(s.Copy,{children:"Product search: after you agree to search, the terms you type, or the name and brand read from a label, go to the NIH Dietary Supplement Label Database. When needed, OpenAI web search locates public manufacturer or retailer pages. Our server retrieves the selected public page and uses OpenAI to transcribe its ingredient text. Formulas can differ by country and change over time: confirm your bottle."}),(0,t.jsx)(s.Copy,{children:"Ask Clarity: prepared answers and in-app guides work locally. Before an online answer, we ask permission to send your question and up to two recent question-and-answer exchanges to OpenAI with our authored guide evidence. Your profile and saved products are not included. Permission lasts for this session and can be turned off in Your space."}),(0,t.jsx)(s.Copy,{children:"Related research: when requested, Consensus receives a general research topic, without your profile, question history or photo. External links open the source website under its own privacy rules."})]}),(0,t.jsxs)(s.Card,{children:[(0,t.jsx)(s.Copy,{kind:"heading",children:"Reports you choose to send"}),(0,t.jsx)(s.Copy,{children:"If you report an answer, we save that answer, your selected reason, its source identifiers, the time and a keyed network hash in a separate private feedback table. Your question, profile and product inventory are not included. We ask before sending. Reports help us review app quality and are kept for up to 31 days, with automatic daily cleanup. They are not a request for medical care. Contact us for a privacy request."})]}),(0,t.jsxs)(s.Card,{children:[(0,t.jsx)(s.Copy,{kind:"heading",children:"Service records and retention"}),(0,t.jsx)(s.Copy,{children:"Apart from answer reports you choose to send, our application does not save photos, copilot conversations or questionnaire answers in its database. AI response storage is disabled in our requests; OpenAI\u2019s retention, abuse-monitoring and other provider controls still apply. This does not promise zero retention. OpenAI, Consensus, NIH and our hosting providers may process requests in other countries, including the United States."}),(0,t.jsx)(s.Copy,{children:"To limit automated abuse and service costs, short-lived request allowances use keyed hashes of network and anonymous session identifiers, without storing the raw network address in our quota database. Hosting providers may keep operational network, security and error logs under their own policies. Successfully retrieved public product metadata may be cached; it does not include your profile or photo."}),(0,t.jsx)(s.Copy,{children:"We do not sell your health answers or use them for advertising. We do not connect to Apple Health, Health Connect or wearables. The app is intended for adults 18 and older."})]}),(0,t.jsxs)(s.Card,{children:[(0,t.jsx)(s.Copy,{kind:"heading",children:"Your choices and contact"}),(0,t.jsx)(s.Copy,{children:"You can use local guides and manual product entry without photo reading or online copilot answers. Device settings control camera and photo access. You choose whether to export or share your entries. For privacy questions or requests, contact MedResearch Academy at info@medresearch-academy.om. Avoid emailing sensitive medical details."})]}),(0,t.jsx)(s.Button,{secondary:!0,label:"Contact MedResearch Academy",onPress:()=>n.default.openURL("mailto:info@medresearch-academy.om")}),(0,t.jsx)(s.Button,{secondary:!0,label:"OpenAI privacy policy",onPress:()=>n.default.openURL("https://openai.com/policies/privacy-policy/")}),(0,t.jsx)(s.Button,{secondary:!0,label:"Consensus privacy policy",onPress:()=>n.default.openURL("https://consensus.app/privacy-policy/")})]})}},775,[221,784,6]);